#!/usr/bin/env bash
set -euo pipefail

C="{{container_name}}"
docker inspect "$C" --format '
=== {{ .Name }} ===
image:    {{ .Config.Image }}
status:   {{ .State.Status }} (started {{ .State.StartedAt }})
restarts: {{ .RestartCount }}
ipv4:     {{ range .NetworkSettings.Networks }}{{ .IPAddress }} {{ end }}
ports:
{{- range $p, $b := .NetworkSettings.Ports }}
  {{ $p }} -> {{ range $b }}{{ .HostIp }}:{{ .HostPort }} {{ end }}
{{- end }}
mounts:
{{- range .Mounts }}
  {{ .Type }} {{ .Source }} -> {{ .Destination }} ({{ if .RW }}rw{{ else }}ro{{ end }})
{{- end }}
env:
{{- range .Config.Env }}
  {{ . }}
{{- end }}
'
